.fxs .pk{--pushA:#FFFFFF;--pushB:#1F6B45;--pushC:#B8862A;--rim:#B8862A;--rimD:#1F6B45}
.fxs .push.pk{--pr:16px;background:none;border-radius:16px;box-shadow:none;filter:drop-shadow(0 8px 0 rgba(20,60,36,.45)) drop-shadow(0 18px 24px rgba(0,0,0,.35))}
.fxs .push.pk span{top:4px;font:700 44px/1 "Kaisei HarunoUmi",serif;letter-spacing:.06em;color:#1E2418;text-shadow:0 2px 0 #E2E6D6}
.fxs .push.pk::after{inset:-22px;top:-38px;border-radius:34px;border-color:rgba(184,134,42,.9)}
.fxs .pk .pkf{position:absolute;left:-10px;top:-26px;width:220px;height:136px;pointer-events:none;font-style:normal}
.fxs .pk .pkf svg{display:block;width:220px;height:136px;overflow:visible}
.fxs .pk .pkd{position:absolute;left:-40px;top:-60px;width:280px;height:190px;pointer-events:none;z-index:3;font-style:normal}
.fxs .pk .pkd svg{display:block;width:280px;height:190px;overflow:visible}
.fxs .pk .pkro{animation:fxpkRo 2.8s ease-in-out infinite alternate}
@keyframes fxpkRo{from{transform:translate(0,-4px) rotate(-8deg)}to{transform:translate(0,4px) rotate(8deg)}}
.fxs .pk .pktw{transform-box:fill-box;transform-origin:50% 50%;animation:fxpkTw 2.6s ease-in-out infinite}
@keyframes fxpkTw{0%,100%{opacity:.15;transform:scale(.45)}50%{opacity:1;transform:scale(1.05) rotate(20deg)}}
.fxs .pshadow.pk{width:220px}
.fxs .tap.pk{font-family:"Kaisei HarunoUmi",serif;font-weight:700;color:#F6E7B8;letter-spacing:.12em;text-shadow:0 2px 0 #163A22,0 0 10px rgba(246,231,184,.6)}
.fxs .pressed.pk{border-radius:16px;background:#FFFFFF;box-shadow:0 0 0 4px #B8862A,0 0 0 7px #1F6B45,0 8px 0 7px #134A2E;animation-name:fxpkPress,fxfxH}
@keyframes fxpkPress{0%{transform:scale(1)}22%{transform:scale(.92)}45%{transform:scale(1.06)}100%{transform:scale(1.45);opacity:0}}
@media (prefers-reduced-motion:reduce){.fxs .pk .pkro,.fxs .pk .pktw{animation:none}
.fxs .clips.pk{display:none}}
.fxs .clips.pk{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
